{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-B8Rann/src/address.js","content":"/**
 * Cell addresses: one or two letters (a column) followed by one to three
 * digits (a row of at least 1). Columns are compared by their base-26 value
 * (A=1 .. Z=26, AA=27 .. ZZ=702) and rows by their numeric value.
 */

/** Converts a run of letters (already upper-cased) into its column index. */
export function columnIndex(letters) {
  let index = 0
  for (const ch of letters) {
    index = index * 26 + (ch.charCodeAt(0) - 64)
  }
  return index
}

/**
 * Checks whether `letters` + `digits` names an addressable cell. `letters`
 * must already be upper-cased. Returns the parsed column index and row
 * number when valid, or null otherwise.
 */
export function resolveAddress(letters, digits) {
  if (letters.length < 1 || letters.length > 2) return null
  if (digits.length < 1 || digits.length > 3) return null
  const row = Number(digits)
  if (!(row >= 1)) return null
  return { col: columnIndex(letters), row, letters, key: `${letters}${row}` }
}

/** Orders two resolved addresses by ascending column then ascending row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

