{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-B8Rann/src/values.js","content":"/**
 * Runtime values: a number, text, a boolean, or an error token. Every value
 * is one of these plain tagged objects.
 */

export const numV = (v) => ({ t: 'num', v })
export const textV = (v) => ({ t: 'text', v })
export const boolV = (v) => ({ t: 'bool', v })
export const errV = (v) => ({ t: 'err', v })

export const isErr = (value) => value.t === 'err'

/**
 * Reads a value as a number for an arithmetic position: booleans become 1
 * or 0, text becomes `#VALUE!`, and an existing error passes through
 * unchanged.
 */
export function asNumber(value) {
  if (value.t === 'num') return value
  if (value.t === 'bool') return numV(value.v ? 1 : 0)
  if (value.t === 'err') return value
  return errV('#VALUE!')
}

/** Rank used to order values of different kinds in a comparison. */
function kindRank(value) {
  if (value.t === 'num') return 0
  if (value.t === 'text') return 1
  return 2
}

/**
 * Compares two non-error values per the spec: same-kind values compare
 * naturally (numbers numerically, text by code point, false below true),
 * and across kinds numbers < text < booleans. Returns -1, 0 or 1.
 */
export function compareValues(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  // booleans: false < true
  const na = a.v ? 1 : 0
  const nb = b.v ? 1 : 0
  return na - nb
}

/** Rounds a finite number to ten significant digits and formats it as JS would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

/** Formats a value for the `values` mode. */
export function formatValue(value) {
  switch (value.t) {
    case 'num':
      return formatNumber(value.v)
    case 'text':
      return value.v
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'err':
      return value.v
    default:
      throw new Error(`unreachable value kind: ${value.t}`)
  }
}
"}

