{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-B8Rann/src/formulaLexer.js","content":"/**
 * Turns a formula body (the text after the leading `=`) into a flat token
 * stream. Throws GrammarError on any character the grammar does not accept;
 * the caller turns that into an `#ERR!` cell.
 */

export class GrammarError extends Error {}

const isLetter = (ch) => ch >= 'A' && ch <= 'Z' || ch >= 'a' && ch <= 'z'
const isDigit = (ch) => ch >= '0' && ch <= '9'

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (isLetter(ch)) {
      let j = i + 1
      while (j < n && isLetter(src[j])) j++
      const letters = src.slice(i, j).toUpperCase()
      let k = j
      while (k < n && isDigit(src[k])) k++
      const digits = src.slice(j, k)
      tokens.push({ type: 'WORD', letters, digits, text: letters + digits })
      i = k
      continue
    }
    if (isDigit(ch)) {
      let j = i + 1
      while (j < n && isDigit(src[j])) j++
      if (src[j] === '.' && isDigit(src[j + 1])) {
        let k = j + 1
        while (k < n && isDigit(src[k])) k++
        tokens.push({ type: 'NUM', value: Number(src.slice(i, k)) })
        i = k
      } else {
        tokens.push({ type: 'NUM', value: Number(src.slice(i, j)) })
        i = j
      }
      continue
    }
    if (ch === '(') { tokens.push({ type: 'LPAREN' }); i++; continue }
    if (ch === ')') { tokens.push({ type: 'RPAREN' }); i++; continue }
    if (ch === ',') { tokens.push({ type: 'COMMA' }); i++; continue }
    if (ch === ':') { tokens.push({ type: 'COLON' }); i++; continue }
    if (ch === '^') { tokens.push({ type: 'OP', op: '^' }); i++; continue }
    if (ch === '*') { tokens.push({ type: 'OP', op: '*' }); i++; continue }
    if (ch === '/') { tokens.push({ type: 'OP', op: '/' }); i++; continue }
    if (ch === '+') { tokens.push({ type: 'OP', op: '+' }); i++; continue }
    if (ch === '-') { tokens.push({ type: 'OP', op: '-' }); i++; continue }
    if (ch === '=') { tokens.push({ type: 'OP', op: '=' }); i++; continue }
    if (ch === '<') {
      if (src[i + 1] === '>') { tokens.push({ type: 'OP', op: '<>' }); i += 2; continue }
      if (src[i + 1] === '=') { tokens.push({ type: 'OP', op: '<=' }); i += 2; continue }
      tokens.push({ type: 'OP', op: '<' }); i++; continue
    }
    if (ch === '>') {
      if (src[i + 1] === '=') { tokens.push({ type: 'OP', op: '>=' }); i += 2; continue }
      tokens.push({ type: 'OP', op: '>' }); i++; continue
    }
    throw new GrammarError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

