 * Recursive-descent parser for a formula body. Produces an AST or throws
 * GrammarError; the caller turns that into an `#ERR!` cell.
 *
 * Precedence, loosest to tightest: comparisons, `+`/`-`, `*`/`/`, `^`, then
 * a leading sign. The comparison, additive and multiplicative levels group
 * left; `^` groups right; a leading sign binds tighter than `^`.
 *
 * A range (`A1:B3`) is only accepted directly as a function call argument.
 */

import { tokenize, GrammarError } from './formulaLexer.js'

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const ADD_OPS = new Set(['+', '-'])
const MUL_OPS = new Set(['*', '/'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  advance() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new GrammarError(`expected ${type}`)
    return this.advance()
  }

  parseFormula() {
    const expr = this.parseExpr()
    if (this.pos !== this.tokens.length) throw new GrammarError('trailing tokens')
    return expr
  }

  parseExpr() {
    return this.parseCompare()
  }

  parseCompare() {
    let left = this.parseAdd()
    while (this.peek() && this.peek().type === 'OP' && COMPARE_OPS.has(this.peek().op)) {
      const op = this.advance().op
      const right = this.parseAdd()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parseAdd() {
    let left = this.parseMul()
    while (this.peek() && this.peek().type === 'OP' && ADD_OPS.has(this.peek().op)) {
      const op = this.advance().op
      const right = this.parseMul()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parseMul() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'OP' && MUL_OPS.has(this.peek().op)) {
      const op = this.advance().op
      const right = this.parsePower()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.peek() && this.peek().type === 'OP' && this.peek().op === '^') {
      this.advance()
      const exponent = this.parsePower()
      return { type: 'Bin', op: '^', left: base, right: exponent }
    }
    return base
  }

  parseUnary() {
    const t = this.peek()
    if (t && t.type === 'OP' && (t.op === '+' || t.op === '-')) {
      this.advance()
      const operand = this.parseUnary()
      return { type: 'Unary', op: t.op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new GrammarError('unexpected end of formula')
    if (t.type === 'NUM') {
      this.advance()
      return { type: 'Num', value: t.value }
    }
    if (t.type === 'LPAREN') {
      this.advance()
      const e = this.parseExpr()
      this.expect('RPAREN')
      return e
    }
    if (t.type === 'WORD') {
      this.advance()
      if (this.peek() && this.peek().type === 'LPAREN') {
        this.advance()
        const args = []
        if (!(this.peek() && this.peek().type === 'RPAREN')) {
          args.push(this.parseArg())
          while (this.peek() && this.peek().type === 'COMMA') {
            this.advance()
            args.push(this.parseArg())
          }
        }
        this.expect('RPAREN')
        return { type: 'Call', name: t.letters, args }
      }
      if (t.digits === '' && t.letters === 'TRUE') return { type: 'Bool', value: true }
      if (t.digits === '' && t.letters === 'FALSE') return { type: 'Bool', value: false }
      return { type: 'Address', letters: t.letters, digits: t.digits }
    }
    throw new GrammarError('unexpected token')
  }

  // A call argument may be a bare range (`A1:B3`); anywhere else `:` is a
  // grammar failure.
  parseArg() {
    const t = this.peek()
    const t1 = this.peek(1)
    const t2 = this.peek(2)
    if (t && t.type === 'WORD' && t1 && t1.type === 'COLON' && t2 && t2.type === 'WORD') {
      this.advance()
      this.advance()
      this.advance()
      return {
        type: 'Range',
        from: { letters: t.letters, digits: t.digits },
        to: { letters: t2.letters, digits: t2.digits },
      }
    }
    return this.parseExpr()
  }
}

/** Parses a formula body into an AST, or returns null if it does not parse. */
export function parseFormula(src) {
  try {
    const tokens = tokenize(src)
    return new Parser(tokens).parseFormula()
  } catch (e) {
    if (e instanceof GrammarError) return null
    throw e
  }
}
"}

