 * Parses the raw sheet text into a map of declared cells. Each line is
 * either blank/a comment (ignored), or `<address><separator><content>`.
 */

import { resolveAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

/**
 * Splits the sheet text into declarations, keyed by canonical address
 * (letters + numeric row). Throws SheetError with a spec-worded message on
 * the first invalid address or duplicate declaration.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let sepIndex = -1
    for (let j = 0; j < stripped.length; j++) {
      if (stripped[j] === ' ' || stripped[j] === '\t') { sepIndex = j; break }
    }
    const addressText = sepIndex === -1 ? stripped : stripped.slice(0, sepIndex)
    const rest = sepIndex === -1 ? '' : stripped.slice(sepIndex)
    const content = rest.replace(/^[ \t]+/, '')

    const upper = addressText.toUpperCase()
    const match = /^([A-Z]{1,2})([0-9]{1,3})$/.exec(upper)
    const address = match ? resolveAddress(match[1], match[2]) : null
    if (!address) {
      throw new SheetError(`line ${lineNumber}: invalid cell address ${upper}`)
    }
    if (cells.has(address.key)) {
      throw new SheetError(`line ${lineNumber}: cell ${address.key} is declared twice`)
    }
    cells.set(address.key, { ...address, content })
  }
  return cells
}
"}

