 * Classifies a declared cell's raw content as a literal value or a formula
 * AST, ready for the evaluator.
 */

import { numV, textV, errV } from './values.js'
import { parseFormula } from './formulaParser.js'

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?\d+(\.\d+)?$/

/** Evaluates literal (non-formula) content into its value. */
export function literalValue(text) {
  if (text === '') return numV(0)
  if (NUMBER_RE.test(text)) return numV(Number(text))
  if (ERROR_TOKENS.has(text)) return errV(text)
  return textV(text)
}

/**
 * Classifies `content` as `{ kind: 'literal', value }` or
 * `{ kind: 'formula', ast }` (ast is null when the formula does not parse).
 */
export function classifyContent(content) {
  if (content.startsWith('=')) {
    return { kind: 'formula', ast: parseFormula(content.slice(1)) }
  }
  return { kind: 'literal', value: literalValue(content) }
}
"}

