 * Expands a range's two corners (in whichever order they were written)
 * into the cells it covers, ordered by ascending column then ascending row.
 */

import { resolveAddress } from './address.js'

/** Returns the list of addresses a range covers, or null if either corner is out of range. */
export function expandRange(from, to) {
  const a = resolveAddress(from.letters, from.digits)
  const b = resolveAddress(to.letters, to.digits)
  if (!a || !b) return null

  const minCol = Math.min(a.col, b.col)
  const maxCol = Math.max(a.col, b.col)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)

  const letters = colIndexToLetters(minCol, maxCol)
  const cells = []
  for (const [col, colLetters] of letters) {
    for (let row = minRow; row <= maxRow; row++) {
      cells.push({ col, row, letters: colLetters, key: `${colLetters}${row}` })
    }
  }
  return cells
}

function colIndexToLetters(minCol, maxCol) {
  const result = []
  for (let col = minCol; col <= maxCol; col++) {
    result.push([col, indexToLetters(col)])
  }
  return result
}

function indexToLetters(index) {
  // index is 1-based (A=1); at most two letters (max index 702 = ZZ).
  if (index <= 26) return String.fromCharCode(64 + index)
  const first = Math.floor((index - 1) / 26)
  const second = index - first * 26
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}
"}

