{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-B8Rann/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheetParser.js'
import { classifyContent } from './content.js'
import { Evaluator } from './evaluator.js'
import { collectDeps } from './deps.js'
import { formatValue } from './values.js'
import { compareAddresses } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  // eslint-disable-next-line no-constant-condition
  while (true) {
    let bytesRead
    try {
      bytesRead = require('node:fs').readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
  }

  const input = readStdin()

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  for (const decl of sheet.values()) {
    decl.parsed = classifyContent(decl.content)
  }

  const sorted = [...sheet.values()].sort(compareAddresses)

  const out = []
  if (mode === 'values') {
    const evaluator = new Evaluator(sheet)
    for (const decl of sorted) {
      const value = evaluator.evaluate(decl.key)
      out.push(`${decl.key}=${formatValue(value)}`)
    }
  } else {
    for (const decl of sorted) {
      const deps = decl.parsed.kind === 'formula' && decl.parsed.ast
        ? collectDeps(decl.parsed.ast)
        : []
      out.push(deps.length ? `${decl.key}: ${deps.join(' ')}` : `${decl.key}:`)
    }
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
}

main()
"}

